window.__code__["rag-parser-pdf-py"] = {"code_id": "rag-parser-pdf-py", "kind": "src", "title": "_pdf.py", "source_path": "agentscope/src/agentscope/rag/_parser/_pdf.py", "highlight_line": null, "code_html": "<div class=\"code-body\">\n<div class=\"c-line\" data-line=\"1\"><span class=\"c-no\">1</span><span class=\"c-src\"><span class=\"c-com\"># -*- coding: utf-8 -*-</span></span></div>\n<div class=\"c-line\" data-line=\"2\"><span class=\"c-no\">2</span><span class=\"c-src\"><span class=\"c-str\">&quot;&quot;</span>&quot;PDF file parser.</span></div>\n<div class=\"c-line\" data-line=\"3\"><span class=\"c-no\">3</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"4\"><span class=\"c-no\">4</span><span class=\"c-src\">One :<span class=\"c-kw\">class</span>:`Section` per page so a downstream</span></div>\n<div class=\"c-line\" data-line=\"5\"><span class=\"c-no\">5</span><span class=\"c-src\">:<span class=\"c-kw\">class</span>:`~agentscope.rag.ChunkerBase` never combines text across page</span></div>\n<div class=\"c-line\" data-line=\"6\"><span class=\"c-no\">6</span><span class=\"c-src\">boundaries.  Each section&<span class=\"c-com\">#x27;s :attr:`Section.metadata` carries the</span></span></div>\n<div class=\"c-line\" data-line=\"7\"><span class=\"c-no\">7</span><span class=\"c-src\">page number (starting at 1) <span class=\"c-kw\">for</span> later citation.</span></div>\n<div class=\"c-line\" data-line=\"8\"><span class=\"c-no\">8</span><span class=\"c-src\"><span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"9\"><span class=\"c-no\">9</span><span class=\"c-src\"><span class=\"c-kw\">import</span> io</span></div>\n<div class=\"c-line\" data-line=\"10\"><span class=\"c-no\">10</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"11\"><span class=\"c-no\">11</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ...message <span class=\"c-kw\">import</span> TextBlock</span></div>\n<div class=\"c-line\" data-line=\"12\"><span class=\"c-no\">12</span><span class=\"c-src\"><span class=\"c-kw\">from</span> .._document <span class=\"c-kw\">import</span> Section</span></div>\n<div class=\"c-line\" data-line=\"13\"><span class=\"c-no\">13</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ._base <span class=\"c-kw\">import</span> ParserBase</span></div>\n<div class=\"c-line\" data-line=\"14\"><span class=\"c-no\">14</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"15\"><span class=\"c-no\">15</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"16\"><span class=\"c-no\">16</span><span class=\"c-src\"><span class=\"c-kw\">class</span> PDFParser(ParserBase):</span></div>\n<div class=\"c-line\" data-line=\"17\"><span class=\"c-no\">17</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;Parser <span class=\"c-kw\">for</span> PDF files.</span></div>\n<div class=\"c-line\" data-line=\"18\"><span class=\"c-no\">18</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"19\"><span class=\"c-no\">19</span><span class=\"c-src\">    Returns one :<span class=\"c-kw\">class</span>:`Section` per page.  Empty / image-only pages</span></div>\n<div class=\"c-line\" data-line=\"20\"><span class=\"c-no\">20</span><span class=\"c-src\">    still produce a Section (<span class=\"c-kw\">with</span> empty text) so the page → section</span></div>\n<div class=\"c-line\" data-line=\"21\"><span class=\"c-no\">21</span><span class=\"c-src\">    correspondence stays exact — downstream chunkers naturally drop</span></div>\n<div class=\"c-line\" data-line=\"22\"><span class=\"c-no\">22</span><span class=\"c-src\">    empty content.</span></div>\n<div class=\"c-line\" data-line=\"23\"><span class=\"c-no\">23</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"24\"><span class=\"c-no\">24</span><span class=\"c-src\">    Requires :mod:`pypdf`; install <span class=\"c-kw\">with</span> ``pip install pypdf`` (<span class=\"c-kw\">or</span> via</span></div>\n<div class=\"c-line\" data-line=\"25\"><span class=\"c-no\">25</span><span class=\"c-src\">    the ``agentscope[rag]`` extra).</span></div>\n<div class=\"c-line\" data-line=\"26\"><span class=\"c-no\">26</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"27\"><span class=\"c-no\">27</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"28\"><span class=\"c-no\">28</span><span class=\"c-src\">    supported_media_types: list[str] = [<span class=\"c-str\">&quot;application/pdf&quot;</span>]</span></div>\n<div class=\"c-line\" data-line=\"29\"><span class=\"c-no\">29</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"30\"><span class=\"c-no\">30</span><span class=\"c-src\">    @classmethod</span></div>\n<div class=\"c-line\" data-line=\"31\"><span class=\"c-no\">31</span><span class=\"c-src\">    <span class=\"c-kw\">def</span> supported_extensions(cls) -&gt; list[str]:</span></div>\n<div class=\"c-line\" data-line=\"32\"><span class=\"c-no\">32</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;Return the canonical ``.pdf`` extension.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"33\"><span class=\"c-no\">33</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> [<span class=\"c-str\">&quot;.pdf&quot;</span>]</span></div>\n<div class=\"c-line\" data-line=\"34\"><span class=\"c-no\">34</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"35\"><span class=\"c-no\">35</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> parse(</span></div>\n<div class=\"c-line\" data-line=\"36\"><span class=\"c-no\">36</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"37\"><span class=\"c-no\">37</span><span class=\"c-src\">        file: bytes | str,</span></div>\n<div class=\"c-line\" data-line=\"38\"><span class=\"c-no\">38</span><span class=\"c-src\">        filename: str,</span></div>\n<div class=\"c-line\" data-line=\"39\"><span class=\"c-no\">39</span><span class=\"c-src\">    ) -&gt; list[Section]:</span></div>\n<div class=\"c-line\" data-line=\"40\"><span class=\"c-no\">40</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Read the PDF bytes <span class=\"c-kw\">and</span> <span class=\"c-kw\">return</span> one Section per page.</span></div>\n<div class=\"c-line\" data-line=\"41\"><span class=\"c-no\">41</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"42\"><span class=\"c-no\">42</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"43\"><span class=\"c-no\">43</span><span class=\"c-src\">            file (`bytes | str`):</span></div>\n<div class=\"c-line\" data-line=\"44\"><span class=\"c-no\">44</span><span class=\"c-src\">                Either the raw PDF bytes, <span class=\"c-kw\">or</span> a filesystem path to</span></div>\n<div class=\"c-line\" data-line=\"45\"><span class=\"c-no\">45</span><span class=\"c-src\">                the PDF file.</span></div>\n<div class=\"c-line\" data-line=\"46\"><span class=\"c-no\">46</span><span class=\"c-src\">            filename (`str`):</span></div>\n<div class=\"c-line\" data-line=\"47\"><span class=\"c-no\">47</span><span class=\"c-src\">                The source filename, copied verbatim into each</span></div>\n<div class=\"c-line\" data-line=\"48\"><span class=\"c-no\">48</span><span class=\"c-src\">                Section&<span class=\"c-com\">#x27;s :attr:`Section.source` field.</span></span></div>\n<div class=\"c-line\" data-line=\"49\"><span class=\"c-no\">49</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"50\"><span class=\"c-no\">50</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"51\"><span class=\"c-no\">51</span><span class=\"c-src\">            `list[Section]`:</span></div>\n<div class=\"c-line\" data-line=\"52\"><span class=\"c-no\">52</span><span class=\"c-src\">                One Section per page, <span class=\"c-kw\">in</span> document order.  Each</span></div>\n<div class=\"c-line\" data-line=\"53\"><span class=\"c-no\">53</span><span class=\"c-src\">                section&<span class=\"c-com\">#x27;s metadata holds ``{\u000013\u0000: &lt;starting at 1&gt;}``.</span></span></div>\n<div class=\"c-line\" data-line=\"54\"><span class=\"c-no\">54</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"55\"><span class=\"c-no\">55</span><span class=\"c-src\">        Raises:</span></div>\n<div class=\"c-line\" data-line=\"56\"><span class=\"c-no\">56</span><span class=\"c-src\">            `FileNotFoundError`: If ``file`` <span class=\"c-kw\">is</span> a ``str`` pointing to</span></div>\n<div class=\"c-line\" data-line=\"57\"><span class=\"c-no\">57</span><span class=\"c-src\">                a path that does <span class=\"c-kw\">not</span> exist.</span></div>\n<div class=\"c-line\" data-line=\"58\"><span class=\"c-no\">58</span><span class=\"c-src\">            `ImportError`: If :mod:`pypdf` <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> installed.</span></div>\n<div class=\"c-line\" data-line=\"59\"><span class=\"c-no\">59</span><span class=\"c-src\">            `ValueError`: If the bytes cannot be parsed <span class=\"c-kw\">as</span> PDF.</span></div>\n<div class=\"c-line\" data-line=\"60\"><span class=\"c-no\">60</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"61\"><span class=\"c-no\">61</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> isinstance(file, str):</span></div>\n<div class=\"c-line\" data-line=\"62\"><span class=\"c-no\">62</span><span class=\"c-src\">            <span class=\"c-kw\">with</span> open(file, <span class=\"c-str\">&quot;rb&quot;</span>) <span class=\"c-kw\">as</span> fp:</span></div>\n<div class=\"c-line\" data-line=\"63\"><span class=\"c-no\">63</span><span class=\"c-src\">                file = fp.read()</span></div>\n<div class=\"c-line\" data-line=\"64\"><span class=\"c-no\">64</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"65\"><span class=\"c-no\">65</span><span class=\"c-src\">        <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"66\"><span class=\"c-no\">66</span><span class=\"c-src\">            <span class=\"c-kw\">from</span> pypdf <span class=\"c-kw\">import</span> PdfReader</span></div>\n<div class=\"c-line\" data-line=\"67\"><span class=\"c-no\">67</span><span class=\"c-src\">            <span class=\"c-kw\">from</span> pypdf.errors <span class=\"c-kw\">import</span> PdfReadError</span></div>\n<div class=\"c-line\" data-line=\"68\"><span class=\"c-no\">68</span><span class=\"c-src\">        <span class=\"c-kw\">except</span> ImportError <span class=\"c-kw\">as</span> e:</span></div>\n<div class=\"c-line\" data-line=\"69\"><span class=\"c-no\">69</span><span class=\"c-src\">            <span class=\"c-kw\">raise</span> ImportError(</span></div>\n<div class=\"c-line\" data-line=\"70\"><span class=\"c-no\">70</span><span class=\"c-src\">                <span class=\"c-str\">&quot;Please install pypdf to use the PDF parser. &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"71\"><span class=\"c-no\">71</span><span class=\"c-src\">                <span class=\"c-str\">&quot;You can install it by `pip install pypdf` (or &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"72\"><span class=\"c-no\">72</span><span class=\"c-src\">                <span class=\"c-str\">&quot;`pip install agentscope[rag]`).&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"73\"><span class=\"c-no\">73</span><span class=\"c-src\">            ) <span class=\"c-kw\">from</span> e</span></div>\n<div class=\"c-line\" data-line=\"74\"><span class=\"c-no\">74</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"75\"><span class=\"c-no\">75</span><span class=\"c-src\">        <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"76\"><span class=\"c-no\">76</span><span class=\"c-src\">            reader = PdfReader(io.BytesIO(file))</span></div>\n<div class=\"c-line\" data-line=\"77\"><span class=\"c-no\">77</span><span class=\"c-src\">        <span class=\"c-kw\">except</span> PdfReadError <span class=\"c-kw\">as</span> e:</span></div>\n<div class=\"c-line\" data-line=\"78\"><span class=\"c-no\">78</span><span class=\"c-src\">            <span class=\"c-kw\">raise</span> ValueError(</span></div>\n<div class=\"c-line\" data-line=\"79\"><span class=\"c-no\">79</span><span class=\"c-src\">                f<span class=\"c-str\">&quot;Failed to parse {filename!r} as PDF: {e}&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"80\"><span class=\"c-no\">80</span><span class=\"c-src\">            ) <span class=\"c-kw\">from</span> e</span></div>\n<div class=\"c-line\" data-line=\"81\"><span class=\"c-no\">81</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"82\"><span class=\"c-no\">82</span><span class=\"c-src\">        sections: list[Section] = []</span></div>\n<div class=\"c-line\" data-line=\"83\"><span class=\"c-no\">83</span><span class=\"c-src\">        <span class=\"c-kw\">for</span> page_idx, page <span class=\"c-kw\">in</span> enumerate(reader.pages, start=1):</span></div>\n<div class=\"c-line\" data-line=\"84\"><span class=\"c-no\">84</span><span class=\"c-src\">            text = page.extract_text() <span class=\"c-kw\">or</span> <span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"85\"><span class=\"c-no\">85</span><span class=\"c-src\">            sections.append(</span></div>\n<div class=\"c-line\" data-line=\"86\"><span class=\"c-no\">86</span><span class=\"c-src\">                Section(</span></div>\n<div class=\"c-line\" data-line=\"87\"><span class=\"c-no\">87</span><span class=\"c-src\">                    content=TextBlock(text=text),</span></div>\n<div class=\"c-line\" data-line=\"88\"><span class=\"c-no\">88</span><span class=\"c-src\">                    source=filename,</span></div>\n<div class=\"c-line\" data-line=\"89\"><span class=\"c-no\">89</span><span class=\"c-src\">                    metadata={<span class=\"c-str\">&quot;page&quot;</span>: page_idx},</span></div>\n<div class=\"c-line\" data-line=\"90\"><span class=\"c-no\">90</span><span class=\"c-src\">                ),</span></div>\n<div class=\"c-line\" data-line=\"91\"><span class=\"c-no\">91</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"92\"><span class=\"c-no\">92</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> sections</span></div>\n<div class=\"c-line\" data-line=\"93\"><span class=\"c-no\">93</span><span class=\"c-src\">&nbsp;</span></div>\n</div>", "lines": 93, "explanation": "_pdf.py 来自 agentscope/QwenPaw 框架源码。结合左侧源码与右侧知识点理解此处设计意图；点「反向链接」可回到引用它的教程章节。", "knowledge_points": [{"title": "RAG", "body": "static（RAGMiddleware 自动检索 HintBlock 一次注入） / agentic（暴露 search_knowledge 工具主动搜）；KnowledgeBase 绑 embedding+vector_store；parser→chunker→embed 入库。"}], "related_docs": ["W08-RAG与多Agent-Team与服务化"]};
